        $sql="SELECT w.id,w.workspace_key,w.name,w.status,w.version,w.created_at,w.updated_at,m.roles,m.status membership_status FROM harpp_workspaces w ".($tenantWide?'LEFT':'INNER')." JOIN harpp_workspace_memberships m ON m.workspace_id=w.id AND m.user_id=:user AND m.status='active'".($tenantWide?'':" WHERE m.id IS NOT NULL")." ORDER BY w.name,w.id";
        $s=$this->database->prepare($sql);$s->execute([':user'=>(int)$actor['id']]);return HarppServiceResult::success(['workspaces'=>$s->fetchAll(PDO::FETCH_ASSOC)]);
    }

