            elseif($action==='policy'){$workspace=(int)($input['workspace_id']??0);$key=strtolower(trim((string)($input['policy_key']??'')));$name=trim(strip_tags((string)($input['name']??'')));$roles=array_values((array)($input['eligible_roles']??['reviewer']));$quorum=(int)($input['quorum']??1);if($workspace<=0||!preg_match('/^[a-z0-9][a-z0-9._-]{2,190}$/',$key)||$name===''||!HarppCollaborationPolicy::validRoles($roles)||$quorum<1)throw new \InvalidArgumentException('Valid workspace policy fields are required.');$s=$this->database->prepare("INSERT INTO harpp_approval_policies(workspace_id,policy_key,name,eligible_roles,eligible_user_ids,quorum,distinct_actors,exclude_creator,exclude_executor,allow_veto,allow_owner_override,allow_delegation,expires_after_seconds,status,version,created_by,created_at,updated_at) VALUES(:workspace,:key,:name,:roles,:users,:quorum,1,:exclude_creator,:exclude_executor,:veto,:override,:delegation,:expiry,'active',1,:actor,NOW(6),NOW(6))");$s->execute([':workspace'=>$workspace,':key'=>$key,':name'=>$name,':roles'=>json_encode($roles,JSON_THROW_ON_ERROR),':users'=>isset($input['eligible_user_ids'])?json_encode(array_values((array)$input['eligible_user_ids']),JSON_THROW_ON_ERROR):null,':quorum'=>$quorum,':exclude_creator'=>!empty($input['exclude_creator'])?1:0,':exclude_executor'=>!empty($input['exclude_executor'])?1:0,':veto'=>!empty($input['allow_veto'])?1:0,':override'=>!empty($input['allow_owner_override'])?1:0,':delegation'=>!empty($input['allow_delegation'])?1:0,':expiry'=>(int)($input['expires_after_seconds']??0)?:null,':actor'=>(int)$actor['id']]);$policy=(int)$this->database->lastInsertId();$event=$this->foundation->recordEffect('harpp.policy.created','policy.created',$actor,'harpp_approval_policy',$policy,null,['workspace_id'=>$workspace,'policy_key'=>$key,'quorum'=>$quorum]);}
