        try{$this->database->beginTransaction();
            if($action==='create'){$key=strtolower(trim((string)($input['project_key']??'')));$name=trim(strip_tags((string)($input['name']??'')));if(!preg_match('/^[a-z0-9][a-z0-9._-]{2,190}$/',$key)||$name==='')throw new \InvalidArgumentException('Valid project_key and name are required.');$s=$this->database->prepare("INSERT INTO harpp_projects(workspace_id,project_key,name,status,created_by,version,created_at,updated_at) VALUES(:workspace,:key,:name,'active',:actor,1,NOW(6),NOW(6))");$s->execute([':workspace'=>$workspace,':key'=>$key,':name'=>$name,':actor'=>(int)$actor['id']]);$project=(int)$this->database->lastInsertId();$this->upsertProjectMember($project,(int)$actor['id'],['manager','operator','reviewer','viewer']);$event=$this->foundation->recordEffect('harpp.project.created','project.created',$actor,'harpp_project',$project,null,['workspace_id'=>$workspace,'project_key'=>$key,'name'=>$name]);}
