        $user=(int)$actor['id'];$role=(string)($actor['role']??'');$scope=$role==='owner'?'1=1':($role==='admin'?"(c.visibility<>'private' OR c.created_by=:creator_user OR EXISTS(SELECT 1 FROM harpp_conversation_participants pg WHERE pg.conversation_id=c.id AND pg.user_id=:private_user AND pg.grant_kind='private_grant' AND pg.revoked_at IS NULL))":"EXISTS(SELECT 1 FROM harpp_workspace_memberships wm WHERE wm.workspace_id=c.workspace_id AND wm.user_id=:workspace_user AND wm.status='active') AND (c.project_id IS NULL OR EXISTS(SELECT 1 FROM harpp_project_memberships pm WHERE pm.project_id=c.project_id AND pm.user_id=:project_user AND pm.status='active')) AND (c.visibility='workspace' OR c.created_by=:creator_user OR (c.visibility='participants' AND EXISTS(SELECT 1 FROM harpp_conversation_participants cp WHERE cp.conversation_id=c.id AND cp.user_id=:participant_user AND cp.revoked_at IS NULL)) OR (c.visibility='private' AND EXISTS(SELECT 1 FROM harpp_conversation_participants pg WHERE pg.conversation_id=c.id AND pg.user_id=:private_user AND pg.grant_kind='private_grant' AND pg.revoked_at IS NULL)))");$sql='INSERT INTO harpp_message_receipts(message_id,user_id,read_at) SELECT m.id,:receipt_user,NOW(6) FROM harpp_messages m JOIN harpp_conversations c ON c.id=m.conversation_id WHERE m.id=:message AND '.$scope.' ON DUPLICATE KEY UPDATE read_at=VALUES(read_at)';$params=[':receipt_user'=>$user,':message'=>$messageId];foreach(['creator_user','private_user','workspace_user','project_user','participant_user']as$key)if(str_contains($sql,':'.$key))$params[':'.$key]=$user;try{$this->database->beginTransaction();$s=$this->database->prepare($sql);$s->execute($params);$recorded=$s->rowCount()>0;$event=$recorded?$this->foundation->recordEffect('harpp.message.receipt.recorded','message.receipt.recorded',$actor,'harpp_message',$messageId,null,['user_id'=>$user,'read'=>true]):null;$this->database->commit();return HarppServiceResult::success(['enabled'=>true,'message_id'=>$messageId,'recorded'=>$recorded],'',array_values(array_filter([$event])),'harpp_message',$messageId);}catch(Throwable $e){if($this->database->inTransaction())$this->database->rollBack();return HarppServiceResult::failure('Unable to record message receipt.',500);}
    }

    public function assignDecision(array $actor,array $input): HarppServiceResult
    {
        $decision=(int)($input['decision_id']??0);$user=(int)($input['user_id']??0);$type=(string)($input['assignment_type']??'assignee');$revoke=filter_var($input['revoke']??false,FILTER_VALIDATE_BOOLEAN);$workspace=0;$project=0;if($decision>0){$scope=$this->database->prepare('SELECT workspace_id,project_id FROM harpp_decisions WHERE id=:id');$scope->execute([':id'=>$decision]);$row=$scope->fetch(PDO::FETCH_ASSOC);$workspace=(int)($row['workspace_id']??0);$project=(int)($row['project_id']??0);}if((!$this->admin($actor)&&!$this->workspaceRole($workspace,(int)$actor['id'],'manager'))||$decision<=0||$user<=0||!in_array($type,['assignee','watcher'],true)||!$this->workspaceMember($workspace,$user)||($project>0&&!$this->projectMember($project,$user)))return HarppServiceResult::failure('Assignment targets must be active members of the decision workspace and narrowed project.',403);
        try{$this->database->beginTransaction();if($revoke){$s=$this->database->prepare('UPDATE harpp_decision_assignments SET revoked_at=NOW(6) WHERE decision_id=:decision AND user_id=:user AND assignment_type=:type AND revoked_at IS NULL');$s->execute([':decision'=>$decision,':user'=>$user,':type'=>$type]);}else{$s=$this->database->prepare('INSERT INTO harpp_decision_assignments(decision_id,user_id,assignment_type,created_by,created_at,revoked_at) VALUES(:decision,:user,:type,:actor,NOW(6),NULL) ON DUPLICATE KEY UPDATE revoked_at=NULL,created_by=VALUES(created_by)');$s->execute([':decision'=>$decision,':user'=>$user,':type'=>$type,':actor'=>(int)$actor['id']]);}$event=$this->foundation->recordEffect('harpp.decision.assignment_changed','decision.assignment_changed',$actor,'harpp_decision',$decision,null,['user_id'=>$user,'assignment_type'=>$type,'revoked'=>$revoke]);$this->database->commit();return HarppServiceResult::success(['decision_id'=>$decision,'user_id'=>$user,'assignment_type'=>$type,'revoked'=>$revoke],'',[$event],'harpp_decision',$decision);}catch(Throwable $e){if($this->database->inTransaction())$this->database->rollBack();return HarppServiceResult::failure('Unable to assign decision.',500);}
    }

    public function approveDecision(array $actor,array $input): HarppServiceResult
    {
        if(!$this->foundation->enabled('approval_policies'))return HarppServiceResult::failure('Approval policies are disabled.',409,'feature_disabled');$decision=(int)($input['decision_id']??0);$vote=(string)($input['vote']??'approve');$reason=trim((string)($input['reason']??''));if($decision<=0||!in_array($vote,['approve','veto'],true)||$reason==='')return HarppServiceResult::failure('Valid decision_id, vote, and reason are required.');
        $eligible=$this->database->prepare("SELECT s.policy_json,s.created_at snapshot_at,d.created_by,wm.roles FROM harpp_decision_policy_snapshots s JOIN harpp_decisions d ON d.id=s.decision_id JOIN harpp_workspace_memberships wm ON wm.workspace_id=d.workspace_id AND wm.user_id=:user AND wm.status='active' WHERE d.id=:decision");$eligible->execute([':user'=>(int)$actor['id'],':decision'=>$decision]);$eligibility=$eligible->fetch(PDO::FETCH_ASSOC);if(!is_array($eligibility))return HarppServiceResult::failure('An active workspace policy snapshot is required.',403);$policy=(array)json_decode((string)$eligibility['policy_json'],true);$roles=(array)json_decode((string)$eligibility['roles'],true);$eligibleRoles=(array)json_decode((string)($policy['eligible_roles']??'[]'),true);$eligibleUsers=(array)json_decode((string)($policy['eligible_user_ids']??'[]'),true);$roleMatch=array_intersect($roles,$eligibleRoles)!==[];$userMatch=in_array((int)$actor['id'],array_map('intval',$eligibleUsers),true);if(!$roleMatch&&!$userMatch)return HarppServiceResult::failure('Actor is not eligible under the snapshotted policy.',403);if(!empty($policy['exclude_creator'])&&(int)$eligibility['created_by']===(int)$actor['id'])return HarppServiceResult::failure('Creator self-approval is excluded.',409,'separation_of_duties');if((int)($policy['expires_after_seconds']??0)>0&&strtotime((string)$eligibility['snapshot_at'])+(int)$policy['expires_after_seconds']<time())return HarppServiceResult::failure('Approval policy snapshot has expired.',409,'approval_expired');
        $delegatedBy=(int)($input['delegated_by']??0);if($delegatedBy>0){if(empty($policy['allow_delegation']))return HarppServiceResult::failure('The snapshotted policy forbids delegation.',409,'delegation_forbidden');$delegation=$this->database->prepare('SELECT 1 FROM harpp_approval_delegations ad JOIN harpp_decisions d ON d.workspace_id=ad.workspace_id WHERE d.id=:decision AND ad.from_user_id=:from_user AND ad.to_user_id=:to_user AND ad.revoked_at IS NULL AND ad.valid_from<=NOW(6) AND ad.expires_at>NOW(6)');$delegation->execute([':decision'=>$decision,':from_user'=>$delegatedBy,':to_user'=>(int)$actor['id']]);if($delegation->fetchColumn()===false)return HarppServiceResult::failure('No active approval delegation exists.',403,'delegation_invalid');}
        try{$this->database->beginTransaction();$s=$this->database->prepare('INSERT INTO harpp_decision_approvals(decision_id,user_id,vote,reason,delegated_by,created_at) VALUES(:decision,:user,:vote,:reason,:delegated,NOW(6))');$s->execute([':decision'=>$decision,':user'=>(int)$actor['id'],':vote'=>$vote,':reason'=>$reason,':delegated'=>$delegatedBy?:null]);$event=$this->foundation->recordEffect('harpp.decision.approved','decision.approved',$actor,'harpp_decision',$decision,null,['vote'=>$vote,'delegated_by'=>$delegatedBy?:null],$reason);$this->database->commit();return HarppServiceResult::success(['decision_id'=>$decision,'vote'=>$vote,'delegated_by'=>$delegatedBy?:null],'',[$event],'harpp_decision',$decision);}catch(Throwable $e){if($this->database->inTransaction())$this->database->rollBack();return HarppServiceResult::failure(str_contains(strtolower($e->getMessage()),'duplicate')?'This reviewer already voted.':'Unable to record approval.',str_contains(strtolower($e->getMessage()),'duplicate')?409:500,str_contains(strtolower($e->getMessage()),'duplicate')?'duplicate_vote':'approval_failed');}
    }

    public function approvalSatisfied(int $decisionId,?int $executorId=null): bool
    {
        if(!$this->foundation->enabled('approval_policies'))return true;$s=$this->database->prepare('SELECT s.policy_json,d.created_by FROM harpp_decision_policy_snapshots s JOIN harpp_decisions d ON d.id=s.decision_id WHERE s.decision_id=:id');$s->execute([':id'=>$decisionId]);$row=$s->fetch(PDO::FETCH_ASSOC);if(!is_array($row))return false;$v=$this->database->prepare('SELECT user_id,vote FROM harpp_decision_approvals WHERE decision_id=:id ORDER BY id');$v->execute([':id'=>$decisionId]);return HarppCollaborationPolicy::approvalSatisfied((array)json_decode((string)$row['policy_json'],true),$v->fetchAll(PDO::FETCH_ASSOC),(int)$row['created_by'],$executorId);
    }

    public function reviewerEligible(int $decisionId,int $userId): bool
    {
        $s=$this->database->prepare("SELECT s.policy_json,wm.roles FROM harpp_decision_policy_snapshots s JOIN harpp_decisions d ON d.id=s.decision_id JOIN harpp_workspace_memberships wm ON wm.workspace_id=d.workspace_id AND wm.user_id=:user AND wm.status='active' WHERE s.decision_id=:decision");$s->execute([':user'=>$userId,':decision'=>$decisionId]);$row=$s->fetch(PDO::FETCH_ASSOC);if(!is_array($row))return false;$policy=(array)json_decode((string)$row['policy_json'],true);$roles=(array)json_decode((string)$row['roles'],true);$eligibleRoles=(array)json_decode((string)($policy['eligible_roles']??'[]'),true);$eligibleUsers=array_map('intval',(array)json_decode((string)($policy['eligible_user_ids']??'[]'),true));return array_intersect($roles,$eligibleRoles)!==[]||in_array($userId,$eligibleUsers,true);
    }

    public function notificationPreferences(array $actor,array $input): HarppServiceResult
    {
