>$channel,'enabled'=>$enabled],'',[$effect],'harpp_notification_preference',$preference);}catch(Throwable $e){if($this->database->inTransaction())$this->database->rollBack();return HarppServiceResult::failure('Unable to save notification preference.',500);}
    }

    public function snapshotPolicy(int $decisionId,int $policyId): void
    {
        if(!$this->foundation->enabled('approval_policies')||$policyId<=0)return;$s=$this->database->prepare("SELECT p.* FROM harpp_approval_policies p JOIN harpp_decisions d ON d.workspace_id=p.workspace_id WHERE p.id=:id AND d.id=:decision AND p.status='active'");$s->execute([':id'=>$policyId,':decision'=>$decisionId]);$policy=$s->fetch(PDO::FETCH_ASSOC);if(!is_array($policy))throw new \InvalidArgumentException('Active approval policy in the decision workspace was not found.');$json=json_encode($policy,JSON_THROW_ON_ERROR);$i=$this->database->prepare('INSERT INTO harpp_decision_policy_snapshots(decision_id,source_policy_id,policy_version,policy_json,created_at) VALUES(:decision,:policy,:version,:json,NOW(6))');$i->execute([':decision'=>$decisionId,':policy'=>$policyId,':version'=>(int)$policy['version'],':json'=>$json]);
    }

    /** Eligible notification recipients; preferences narrow fanout but never grant visibility. */
    public function notificationRecipients(int $workspaceId,?int $conversationId,string $eventType,int $excludeUser=0): array
    {
        $sql="SELECT DISTINCT u.id FROM harpp_users u LEFT JOIN harpp_workspace_memberships wm ON wm.user_id=u.id AND wm.workspace_id=:membership_workspace AND wm.status='active' LEFT JOIN harpp_notification_preferences np ON np.user_id=u.id AND (np.workspace_id=:preference_workspace OR np.workspace_id IS NULL) AND np.event_type=:event AND np.channel='in_app' WHERE u.is_active=1 AND u.deleted_at IS NULL AND u.id<>:exclude AND (u.role='owner' OR wm.id IS NOT NULL) AND COALESCE(np.enabled,1)=1";$params=[':membership_workspace'=>$workspaceId,':preference_workspace'=>$workspaceId,':event'=>$eventType,':exclude'=>$excludeUser];
        if($conversationId!==null){$sql.=" AND EXISTS(SELECT 1 FROM harpp_conversations c WHERE c.id=:conversation AND (u.role='owner' OR ((c.project_id IS NULL OR EXISTS(SELECT 1 FROM harpp_project_memberships pm WHERE pm.project_id=c.project_id AND pm.user_id=u.id AND pm.status='active')) AND (c.visibility='workspace' OR (c.visibility='participants' AND (c.created_by=u.id OR EXISTS(SELECT 1 FROM harpp_conversation_participants cp WHERE cp.conversation_id=c.id AND cp.user_id=u.id AND cp.revoked_at IS NULL))) OR (c.visibility='private' AND (c.created_by=u.id OR EXISTS(SELECT 1 FROM harpp_conversation_participants pg WHERE pg.conversation_id=c.id AND pg.user_id=u.id AND pg.grant_kind='private_grant' AND pg.revoked_at IS NULL))))))";$params[':conversation']=$conversationId;}
        $sql.=' ORDER BY u.id';$s=$this->database->prepare($sql);$s->execute($params);return array_map('intval',$s->fetchAll(PDO::FETCH_COLUMN));
    }

    private function upsertWorkspaceMember(int $workspace,int $user,array $roles,int $creator):void{$s=$this->database->prepare("INSERT INTO harpp_workspace_memberships(workspace_id,user_id,roles,status,created_by,version,created_at,updated_at) VALUES(:workspace,:user,:roles,'active',:creator,1,NOW(6),NOW(6)) ON DUPLICATE KEY UPDATE roles=VALUES(roles),status='active',version=version+1");$s->execute([':workspace'=>$workspace,':user'=>$user,':roles'=>json_encode($roles,JSON_THROW_ON_ERROR),':creator'=>$creator]);}
    private function upsertProjectMember(int $project,int $user,array $roles):void{$s=$this->database->prepare("INSERT INTO harpp_project_memberships(project_id,user_id,roles,status,created_at) VALUES(:project,:user,:roles,'active',NOW(6)) ON DUPLICATE KEY UPDATE roles=VALUES(roles),status='active'");$s->execute([':project'=>$project,':user'=>$user,':roles'=>json_encode($roles,JSON_THROW_ON_ERROR)]);}
    private function workspaceMember(int $workspace,int $user):bool{$s=$this->database->prepare("SELECT 1 FROM harpp_workspace_memberships WHERE workspace_id=:workspace AND user_id=:user AND status='active'");$s->execute([':workspace'=>$workspace,':user'=>$user]);return$s->fetchColumn()!==false;}
    private function workspaceRole(int $workspace,int $user,string $role):bool{$s=$this->database->prepare("SELECT 1 FROM harpp_workspace_memberships WHERE workspace_id=:workspace AND user_id=:user AND status='active' AND JSON_CONTAINS(roles,:role)");$s->execute([':workspace'=>$workspace,':user'=>$user,':role'=>json_encode($role)]);return$s->fetchColumn()!==false;}
    private function projectInWorkspace(int $project,int $workspace):bool{$s=$this->database->prepare('SELECT 1 FROM harpp_projects WHERE id=:project AND workspace_id=:workspace');$s->execute([':project'=>$project,':workspace'=>$workspace]);return$s->fetchColumn()!==false;}
    private function projectMember(int $project,int $user):bool{$s=$this->database->prepare("SELECT 1 FROM harpp_project_memberships WHERE project_id=:project AND user_id=:user AND status='active'");$s->execute([':project'=>$project,':user'=>$user]);return$s->fetchColumn()!==false;}
    private function canManageConversation(int $conversation,array $actor):bool{if($this->admin($actor))return true;$s=$this->database->prepare("SELECT 1 FROM harpp_conversations c JOIN harpp_workspace_memberships wm ON wm.workspace_id=c.workspace_id AND wm.user_id=:member_user AND wm.status='active' WHERE c.id=:conversation AND JSON_CONTAINS(wm.roles,'\"manager\"')");$s->execute([':conversation'=>$conversation,':member_user'=>(int)$actor['id']]);return$s->fetchColumn()!==false;}
    private function admin(array $actor):bool{return(int)($actor['id']??0)>0&&in_array((string)($actor['role']??''),['owner','admin'],true);}
}
